import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Euler } = ctx.THREE;

  const group = new Group();
  group.userData.cleanup = () => {};

  // Create plane geometry
  const geometry = new PlaneGeometry(1, 1);

  // Load texture asynchronously
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    texture.colorSpace = 'srgb';

    // Create material with TSL nodes for subtle gradient overlay
    const uvNode = uv();
    const gradientStrength = 0.12;

    // Vertical gradient from paper to surface
    const gradient = mix(
      color(0x16161d),
      color(0xe8ecf2),
      vec3(uvNode.y)
    );

    // Blend texture with gradient using mix node
    const textureColor = color(texture);
    const blended = mix(textureColor, gradient, gradientStrength);

    const material = new MeshBasicNodeMaterial({
      colorNode: blended,
      map: texture,
      transparent: true,
    });

    const plane = new Mesh(geometry, material);
    plane.position.set(config.scenePosition?.[0] ?? 3.2, config.scenePosition?.[1] ?? 1, config.scenePosition?.[2] ?? 0.06);

    if (config.scenePosition?.[3] !== undefined || config.scenePosition?.[4] !== undefined || config.scenePosition?.[5] !== undefined) {
      plane.rotation.set(
        config.scenePosition?.[3] ?? 0,
        config.scenePosition?.[4] ?? 0,
        config.scenePosition?.[5] ?? 0
      );
    }

    if (config.scenePosition?.[6] !== undefined || config.scenePosition?.[7] !== undefined || config.scenePosition?.[8] !== undefined) {
      plane.scale.set(
        config.scenePosition?.[6] ?? 1,
        config.scenePosition?.[7] ?? 1,
        config.scenePosition?.[8] ?? 1
      );
    }

    group.add(plane);
  });

  // Render text content
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textY = 0.25;

  for (const item of textItems) {
    if (item.text) {
      const fontSize = item.typography?.fontSize ?? 39;
      const textMesh = ctx.fontAtlas.createText(String(item.text), {
        fontSize: fontSize,
        color: '#e8ecf2',
        align: 'center',
      });

      textMesh.position.y = textY;
      textMesh.position.z = 0.1;
      group.add(textMesh);
      textY -= 0.2;
    }
  }

  return group;
}
